  minorRecap: { en: 'You were there. Under 18 nothing is scored, so this card shows no Index: the circle you met and the sessions you went to are below.', ta: 'நீங்கள் அங்கே இருந்தீர்கள். 18 வயதுக்குக் கீழ் எதற்கும் மதிப்பெண் இல்லை, எனவே இந்த அட்டையில் குறியீடு இல்லை: நீங்கள் சந்தித்த வட்டமும் சென்ற அமர்வுகளும் கீழே உள்ளன.', hi: 'आप वहाँ थे। 18 से कम उम्र में कुछ भी स्कोर नहीं होता, इसलिए इस कार्ड पर कोई इंडेक्स नहीं है: जिस सर्कल से आप मिले और जिन सत्रों में गए, वे नीचे हैं।' },
  keepsTitle: { en: 'Your invitation and badge · Joyspan 2027', ta: 'உங்கள் அழைப்பும் அடையாள அட்டையும் · Joyspan 2027', hi: 'आपका निमंत्रण और बैज · Joyspan 2027' },
  keepsBody: { en: 'Kept from the edition you attended. The badge says what you agreed to in words, not ticks.', ta: 'நீங்கள் கலந்துகொண்ட பதிப்பிலிருந்து வைக்கப்பட்டவை. நீங்கள் ஒப்புக்கொண்டதை அடையாள அட்டை டிக் குறிகளால் அல்ல, சொற்களால் சொல்கிறது.', hi: 'जिस संस्करण में आप आए, वहाँ से रखा हुआ। बैज आपकी सहमति टिक से नहीं, शब्दों में बताता है।' },
